type Promo = { name: string; applies: (subtotal: number) => boolean; amount: (subtotal: number) => number };

const promos: Promo[] = [
  { name: "weekend", applies: () => true, amount: () => 500 },
  { name: "bulk", applies: (s) => s >= 50000, amount: () => 2500 },
  { name: "ten", applies: (s) => s >= 10000, amount: (s) => Math.round(s * 0.1) },
];

function best(subtotal: number): string {
  let winner = { name: "none", amount: 0 };
  for (const p of promos) {
    if (p.applies(subtotal) && p.amount(subtotal) > winner.amount) winner = { name: p.name, amount: p.amount(subtotal) };
  }
  return `${winner.name}:${winner.amount}`;
}

