type Invoice = { number: string; customer: string; totalKobo: number };

function toAccountingRow(invoice: Invoice): string {
  const field = (value: string | number) => {
    const text = String(value);
    return /[",\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
  };
  return [invoice.number, invoice.customer, invoice.totalKobo].map(field).join(",");
}

console.log(toAccountingRow({ number: "INV-8", customer: "Musa, Sons & Co", totalKobo: 950000 }));

